func sanitizeForAgentType(agentType types.AgentType, data []byte) []byte {
	if len(data) == 0 {
		return data
	}
	if agentType == agent.AgentTypeCodex {
		return codex.SanitizePortableTranscript(data)
	}
	return data
}

